      "content": "这个字帖很适合初学书友，用来建立结构意识，练习手感。也很适合写了很久文征明小楷没有进步，写什么都像文征明的书友，可以写一写这个，这个字帖很“长字”，对于以后学其他帖很有帮助。\n这款笔是我专门定制适合写欧体小楷的紫毫小楷笔，短虚锋，软硬适中，好控笔，关键价格非常实惠，书友们一定要试试哇😄\n#行书 #小楷入门 #小楷 #楷书 #书法最能静心 #书法是一种生活状态 #练字是一种生活",
