      "workId": "6a9183b1000000002902823c",
      "title": "原来唐代人这样写草书……看完我悟了‼️",
      "content": "学草书的朋友有没有这种感觉！\n照着《书谱》《十七帖》一顿猛练，写出来总觉得哪里不对？线条太匀、太稳、太“平”了！\n\t\n📙 直到我看到《敦煌书法集萃》第三册《唐人草书》 里，直接傻眼！[惊恐R]\n\t\n✍️ 我们平时看的草书字帖大多是碑刻拓本，经过刀刻、翻印、千年风化，早失真了！线条被磨得均匀平滑，提按飞白全没了！但敦煌藏经洞的唐人草书墨迹不一样！\n\t\n[一R] 就拿《妙法莲华经玄赞卷》来说，草法精准得体，“佛”字直接草作“仏”，“菩萨”省为“十一”，干净利落！笔法绞转微妙，书写气息连贯！\n\t\n更妙的是，这些草书还保留着隶书的余韵，字字独立，意趣一贯，朴拙天然！跟我们今天理解的纯连绵草书完全是两回事！[得意R]\n\t\n[二R] 再看《净名经关中疏卷上》，乌丝栏若隐若现，笔迹自由随性，夹杂着朱砂笔批阅校正的痕迹，上面还留着罗振玉、康生这些收藏大家的钤印！一千年来的流转，全在这些墨迹里了！[派对R]\n\t\n本书167页，4件唐代草书手稿原色高清影印，连带使转、牵丝飞白，清清楚楚，每一笔都看得见古人真实的运笔轨迹！[派对R]\n\t\n关键是，这套书不只有草书！\n📕《隋人小楷》103页｜5件隋代真迹，看晋唐怎么过渡\n📗《唐人小楷》125页｜6件盛唐手稿，成熟唐楷长这样\n📘《唐人草书》167页｜4件唐代草书，看完直接悟了\n📙《敦煌残纸》130页｜16件珍稀残卷，原生态民间笔迹\n\t\n💝 全套重4.2斤，外带函套，锁线可180度平摊，临摹顺手！[派对R]\n\t\n💰 原价392元！现在只要168元！一本才40多块。\n想真正搞懂草书的朋友，这套真迹，真的值得冲🔥\n\t\n🛒 点击下方链接即可购买👇\n\t\n#敦煌书法 #敦煌墨迹 #隋人小楷 #唐人小楷 #唐人草书 #敦煌残纸 #书法字帖 #练字好物 #小楷临摹 #草书练习 #古帖推荐 #书法进阶 #抄经字帖 #小众书法 #练字打卡 #敦煌字帖 #毛笔临摹\n",
