      "content": "这支鸡狼毫小楷，写起来是真的丝滑顺手，用过就懂。出锋1.8cm，口径0.65cm，这个规格写小楷刚刚好。笔杆是天然老竹，两端嵌了玛瑙，温润有质感，握在手里很舒服。笔头的搭配很见功夫：狼毫作柱，撑起弹性与骨力；鸡毫为披，增加蓄墨量。鸡毫本身柔软细腻，披覆在狼毫外面，既保留了狼毫的劲挺，又让笔头更饱满、下墨更从容。最省心的是笔锋天然聚拢，不用特意调锋，提笔就能写得干净利落。这种做工，原价78元已经很值了。现在小红书放漏36元一支。库存只有50单，需要的书友抓紧哦，趁活动赶紧入手吧！#毛笔 #瘦金体毛笔 #毛笔推荐 #毛笔书法 #毛笔字自学 #国画 #小楷 #写字 #勾线 #灵飞经 ",
