      "workId": "6a917f24000000002103387c",
      "title": "西安成人、少儿一对一书法（硬笔、毛笔都可）",
      "content": "王老师，毕业于西安美术学院，获学士学位。陕西省书法家协会会员、陕西省美术家协会会员、国家心理咨询师三级、美术教师资格、中国教育部书画等级考试书法九级（最高级）。曾任西安小学、西安师范附属小学书法兴趣课教师。从事少儿书画培训十余年，很好地践行“因材施教”，辅导学生参加教育部书法考级通过率98%。作品多次参加省内外展览，毕业创作获得西安美术学院红星宣纸奖三等奖，书法作品入选陕西省第二届书法篆刻展，国画山水作品入选2017~2019“帼真如此”“意绘青春”展并被亮宝楼永久收藏。\n学生曾获得西安市优秀书法少年。中国教育部书画等级考试七级、五级。陕西省中小学艺术展演二等奖，陕西省中小学美育展演二等奖、优秀奖，新城区中小学艺术展演一等奖、二等奖。西安春芽杯二等奖等。\n#西安书法班 #西安夜校 #西安少儿书法 #西安书法 #西安成人书法 #毛笔书法 #西安书法培训 #西安成人书法班 #少儿书法 #成人书法",
