      "title": "今天朋友和我说，他自己练了好一段时间，却一直被一个问题困扰——他作为新手，手总是不听使唤，还容易乱抖。我这就分享个七天的训练技巧，#书法教学#零基础入门书法#书法技巧#书法教学#成人书法",
